"""Decide how much of an expense each person owes."""

from tabtally.errors import MoneyError
from tabtally.money import allocate

FULL_PERCENT = 100


def split_equally(cents: int, people: list[str]) -> dict[str, int]:
    _reject_duplicates(people)
    return dict(zip(people, allocate(cents, [1] * len(people))))


def split_by_percent(cents: int, percents: dict[str, int]) -> dict[str, int]:
    total = sum(percents.values())
    if total != FULL_PERCENT:
        raise MoneyError(f"percentages must add up to {FULL_PERCENT}, not {total}")
    return dict(zip(percents, allocate(cents, list(percents.values()))))


def parse_percents(options: list[str]) -> dict[str, int]:
    """Turn "NAME=PCT" options such as ["alice=50", "bob=50"] into {"alice": 50, "bob": 50}."""
    names = []
    percents = {}
    for option in options:
        name, separator, text = option.partition("=")
        if not separator or not name:
            raise MoneyError(f"expected NAME=PCT, got {option!r}")
        if not text.isdecimal() or int(text) == 0:
            raise MoneyError(f"percentage must be a whole number above zero: {option!r}")
        names.append(name)
        percents[name] = int(text)
    _reject_duplicates(names)
    return percents


def _reject_duplicates(names: list[str]) -> None:
    duplicates = sorted({name for name in names if names.count(name) > 1})
    if duplicates:
        raise MoneyError(f"listed more than once: {', '.join(duplicates)}")

